{
  "facts": [
    {
      "entity": "coat rack",
      "fact": "There are four coats on the rack by the door.",
      "certainty": "established",
      "evidence": "counted the coats on the rack by the door: four"
    },
    {
      "entity": "Nadia",
      "fact": "She hung three coats on arrival, and her own coat is the fourth.",
      "certainty": "established",
      "evidence": "She had hung three when she arrived, and her own made four"
    },
    {
      "entity": "the back office",
      "fact": "No one new arrived while Nadia was waiting.",
      "certainty": "inferred",
      "evidence": "so no one new had come while she waited"
    },
    {
      "entity": "the meeting",
      "fact": "Nadia expects the meeting to go badly.",
      "certainty": "character_belief",
      "evidence": "the meeting would go badly — they always did — but she had no reason yet to think so"
    },
    {
      "entity": "envelope on the desk",
      "fact": "An unopened envelope on the desk has Nadia's name misspelled.",
      "certainty": "established",
      "evidence": "a single unopened envelope with her name misspelled"
    }
  ],
  "insufficient_evidence": [
    "Who Nadia is meeting or what the meeting concerns",
    "Why her name is misspelled on the envelope",
    "What the envelope contains"
  ]
}

{
  "facts": [
    {
      "entity": "Uncle Bramwell",
      "fact": "Uncle Bramwell is dead, confirmed by the physician on Tuesday.",
      "certainty": "established",
      "evidence": "Uncle Bramwell is dead; the physician confirmed it Tuesday"
    },
    {
      "entity": "the will",
      "fact": "Edith is certain Bramwell changed the will in her favour before he died.",
      "certainty": "character_belief",
      "evidence": "I am certain he changed the will in my favour before the end"
    },
    {
      "entity": "the orchard",
      "fact": "Edith says Bramwell repeatedly promised her the orchard.",
      "certainty": "character_belief",
      "evidence": "He promised me the orchard a hundred times"
    },
    {
      "entity": "Margaret",
      "fact": "Edith reports that Margaret disputes her account of the will.",
      "certainty": "established",
      "evidence": "Margaret says otherwise, but Margaret would"
    },
    {
      "entity": "Edith",
      "fact": "Edith asks the cousin to come at once for the reading of the will.",
      "certainty": "established",
      "evidence": "Come at once — I cannot face the reading alone"
    }
  ],
  "insufficient_evidence": [
    "Whether Bramwell actually changed the will in Edith's favour",
    "The true contents of the will",
    "Whether Bramwell in fact promised Edith the orchard"
  ]
}

{
  "facts": [
    {
      "entity": "the room",
      "fact": "The room smells of camphor and something older.",
      "certainty": "established",
      "evidence": "The room smelled of camphor and something older"
    },
    {
      "entity": "the window",
      "fact": "Fog against the window obscures the garden.",
      "certainty": "established",
      "evidence": "Fog pressed the window until the garden was only a rumour of grey"
    },
    {
      "entity": "the clock",
      "fact": "The clock has stopped, at an unknown time.",
      "certainty": "established",
      "evidence": "The clock had stopped, though she could not say when"
    }
  ],
  "insufficient_evidence": [
    "Whether a person is present behind the curtain (the breathing is explicitly offered as possibly the house settling)",
    "Who 'she' is and why she is waiting",
    "What decision was made, and by whom",
    "When the clock stopped"
  ]
}

{
  "facts": [
    {
      "entity": "the chart",
      "fact": "The chart is old and its ink has faded most along the eastern march.",
      "certainty": "established",
      "evidence": "The ink had faded most along the eastern march"
    },
    {
      "entity": "the ford",
      "fact": "A mule drowned at the ford.",
      "certainty": "established",
      "evidence": "the ford where the mule had drowned"
    },
    {
      "entity": "Sela",
      "fact": "A ridge was named for Sela, who died before the chart was drawn.",
      "certainty": "established",
      "evidence": "the ridge they had named for Sela, who had not lived to see it drawn"
    },
    {
      "entity": "the coastline",
      "fact": "The cartographer did not survey the coast; he copied it, trusting a sailor's account.",
      "certainty": "established",
      "evidence": "that stretch he had copied, trusting a sailor's word"
    },
    {
      "entity": "the copied coastline",
      "fact": "The cartographer distrusts the copied coastline and has felt uneasy about it since.",
      "certainty": "character_belief",
      "evidence": "it had never sat right with him since"
    },
    {
      "entity": "the eastern march of the chart",
      "fact": "The eastern march may be less reliably drawn, since his hand shook worst there.",
      "certainty": "inferred",
      "evidence": "the eastern march, where his hand had shaken worst"
    }
  ],
  "insufficient_evidence": [
    "Whether the copied coastline is actually inaccurate",
    "How Sela died",
    "Whether the sailor's account was correct"
  ]
}

